import openpyxl, hashlib
# Compare answer files 1,2,3 fully (cell values only)
files=['/mnt/hhq/data/answer_files/1_55427_answer.xlsx','/mnt/hhq/data/answer_files/2_55427_answer.xlsx','/mnt/hhq/data/answer_files/3_55427_answer.xlsx']
wbs=[openpyxl.load_workbook(f, data_only=False) for f in files]
for si in range(3):
    for pair in [(0,1),(1,2)]:
        a=wbs[pair[0]].worksheets[si]; b=wbs[pair[1]].worksheets[si]
        diffs=0
        for row in range(1, a.max_row+1):
            for col in range(1, a.max_column+1):
                av=a.cell(row=row,column=col).value; bv=b.cell(row=row,column=col).value
                if av!=bv:
                    diffs+=1
                    if diffs<5: print('diff', si, pair, a.title, row,col,repr(av),repr(bv))
        print('sheet',si,a.title,'diffs between',pair,diffs)
